begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into fontex_beta.invitations(email) values('class-teacher@example.invalid'),('class-student@example.invalid'),('class-outsider@example.invalid');
insert into auth.users(id,email) values
('c1a55000-0000-4000-8000-000000000001','class-teacher@example.invalid'),
('c1a55000-0000-4000-8000-000000000002','class-student@example.invalid'),
('c1a55000-0000-4000-8000-000000000003','class-outsider@example.invalid');
update auth.users set email_confirmed_at=now() where id::text like 'c1a55000%';
insert into public.organizations(id,name,created_by) values('c1a55001-0000-4000-8000-000000000001','Escuela','c1a55000-0000-4000-8000-000000000001');
insert into public.classrooms(id,organization_id,title,owner_id) values('c1a55002-0000-4000-8000-000000000001','c1a55001-0000-4000-8000-000000000001','Clase modelo','c1a55000-0000-4000-8000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select extensions.throws_ok($$select public.create_classroom_join_link('c1a55002-0000-4000-8000-000000000001')$$,'42501','classroom_permission_denied','outsider cannot create class links');
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.class_link',public.create_classroom_join_link('c1a55002-0000-4000-8000-000000000001')::text,true);
select extensions.ok(current_setting('test.class_link')::jsonb->>'code' ~ '^[A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{4}$','short code is readable and random');
reset role;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select extensions.is(public.get_classroom_join_info(current_setting('test.class_link')::jsonb->>'code')->>'title','Clase modelo','anonymous visitor resolves code');
select extensions.is(public.get_classroom_join_info('INVALID'),null,'invalid invitation reveals no classroom');
select extensions.throws_ok($$select public.start_classroom_guest('INVALID','Ana')$$,'22023','classroom_invite_expired','invalid link cannot create guest');
select extensions.throws_ok($$select public.start_classroom_guest(current_setting('test.class_link')::jsonb->>'token','   ')$$,'22023','classroom_name_required','guest needs a real name');
select set_config('test.class_guest',public.start_classroom_guest(current_setting('test.class_link')::jsonb->>'token','Ana')::text,true);
select extensions.is(public.get_classroom_guest(current_setting('test.class_guest')::jsonb->>'token')->>'display_name','Ana','guest returns on the same browser credential');
select extensions.is(public.get_classroom_guest('forged'),null,'forged guest cannot read participation');
select extensions.ok(not has_function_privilege('anon','public.list_classroom_guests(uuid)','execute'),'guest cannot list other participants');
select extensions.ok(not has_function_privilege('anon','public.complete_classroom_guest(text)','execute'),'guest cannot promote without an account');
select set_config('request.path','/rpc/start_classroom_guest',true);
select extensions.lives_ok('select fontex_beta.check_request()','guest endpoint is admitted by request gate');
select set_config('request.path','/visual_scenes',true);
select extensions.throws_ok('select fontex_beta.check_request()','42501','beta_invitation_required','guest cannot bypass the private API gate');
select set_config('request.path','/rpc/read_public_canvas',true);
select extensions.lives_ok('select fontex_beta.check_request()','public canvas endpoint still works');
reset role;
-- A legitimate existing Auth account may join even before Fontex admission.
delete from fontex_beta.members where user_id='c1a55000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.is(public.join_classroom_by_invite(current_setting('test.class_link')::jsonb->>'code'),'c1a55002-0000-4000-8000-000000000001'::uuid,'existing account joins with code');
select extensions.is(public.join_classroom_by_invite(current_setting('test.class_link')::jsonb->>'token'),'c1a55002-0000-4000-8000-000000000001'::uuid,'repeated join by link is idempotent');
select extensions.throws_ok($$select public.list_classroom_guests('c1a55002-0000-4000-8000-000000000001')$$,'42501','classroom_permission_denied','student cannot inspect temporary roster');
reset role;
select extensions.is((select role::text from public.class_members where classroom_id='c1a55002-0000-4000-8000-000000000001' and user_id='c1a55000-0000-4000-8000-000000000002'),'student','shared invitations can only grant student role');
update fontex_beta.members set active=false where user_id='c1a55000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.throws_ok($$select public.join_classroom_by_invite(current_setting('test.class_link')::jsonb->>'code')$$,'42501','classroom_permission_denied','class link cannot reactivate a revoked account');
reset role;
update fontex_beta.members set active=true where user_id='c1a55000-0000-4000-8000-000000000002';
update public.class_members set status='removed' where user_id='c1a55000-0000-4000-8000-000000000002';
set local role authenticated;
select extensions.throws_ok($$select public.join_classroom_by_invite(current_setting('test.class_link')::jsonb->>'code')$$,'42501','classroom_membership_removed','removed student cannot rejoin using the old code');
reset role;
select extensions.throws_ok($$insert into auth.users(id,email,raw_user_meta_data) values('c1a55000-0000-4000-8000-000000000099','forged@example.invalid','{"classroom_guest_token":"forged","role":"teacher"}')$$,'42501',null,'untrusted metadata cannot authorize registration');
insert into auth.users(id,email,raw_user_meta_data) values('c1a55000-0000-4000-8000-000000000004','ana@example.invalid',jsonb_build_object('classroom_guest_token',current_setting('test.class_guest')::jsonb->>'token','display_name','Ana'));
select extensions.is(fontex_beta.allowed('c1a55000-0000-4000-8000-000000000004'),false,'upgrade still requires email confirmation');
select extensions.throws_ok($$insert into auth.users(id,email,raw_user_meta_data) values('c1a55000-0000-4000-8000-000000000005','second@example.invalid',jsonb_build_object('classroom_guest_token',current_setting('test.class_guest')::jsonb->>'token'))$$,'42501',null,'guest signup credential is single use');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select extensions.throws_ok($$select public.complete_classroom_guest(current_setting('test.class_guest')::jsonb->>'token')$$,'42501','classroom_guest_expired','different account cannot claim registered guest');
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select extensions.throws_ok($$select public.complete_classroom_guest(current_setting('test.class_guest')::jsonb->>'token')$$,'42501','classroom_verified_account_required','unconfirmed upgrade cannot become permanent');
reset role;
update auth.users set email_confirmed_at=now() where id='c1a55000-0000-4000-8000-000000000004';
select extensions.is((select role::text from public.class_members where classroom_id='c1a55002-0000-4000-8000-000000000001' and user_id='c1a55000-0000-4000-8000-000000000004'),'student','email confirmation enrolls the account even on another device');
update private.classroom_guests set expires_at=now()-interval '1 minute' where id=(current_setting('test.class_guest')::jsonb->>'id')::uuid;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select extensions.lives_ok($$select public.complete_classroom_guest(current_setting('test.class_guest')::jsonb->>'token')$$,'confirmed account can finish after temporary class ends');
select extensions.lives_ok($$select public.complete_classroom_guest(current_setting('test.class_guest')::jsonb->>'token')$$,'promotion retries are idempotent');
select set_config('request.jwt.claims','{"sub":"c1a55000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is(jsonb_array_length(public.list_classroom_guests('c1a55002-0000-4000-8000-000000000001')),0,'promoted or expired guests leave temporary roster');
select set_config('test.class_guest2',public.start_classroom_guest(current_setting('test.class_link')::jsonb->>'code','Luis')::text,true);
select extensions.is(jsonb_array_length(public.list_classroom_guests('c1a55002-0000-4000-8000-000000000001')),1,'teacher sees active temporary participants');
select public.revoke_classroom_join_link('c1a55002-0000-4000-8000-000000000001');
select extensions.is(public.get_classroom_join_info(current_setting('test.class_link')::jsonb->>'token'),null,'revoked link no longer resolves');
select extensions.is(public.get_classroom_guest(current_setting('test.class_guest2')::jsonb->>'token'),null,'revocation ends temporary access');
select extensions.is((select count(*)::int from public.class_members where classroom_id='c1a55002-0000-4000-8000-000000000001'),3,'revocation preserves permanent memberships');
reset role;
select extensions.ok(not has_table_privilege('anon','private.classroom_guests','select'),'guest names are not a public roster');
select extensions.ok(not has_table_privilege('authenticated','private.classroom_guests','select'),'authenticated outsiders cannot read raw guest records');
select * from extensions.finish();
rollback;
